@startuml

class Student {
  +studentID : string
  +dateOfBirth : date
  +cityOfBirth : string
  +regionOfBirth : string
}

class Professor {
  +name : string
  +dateOfBirth : date
  +cityOfBirth : string
}

class Faculty {
  +name : string
  +type : string
}

class Course {
  +code : string
  +lectureHours : int
}

class Exam {
  +grade : string
}

class EnrolledIn {
  +yearOfEnrollment : int
}

Student "1" -- "1" Faculty : enrolled_in
Student "1" -- "*" EnrolledIn
EnrolledIn -- "1" Faculty
Student "1" -- "*" Exam
Exam -- "1" Course
Professor "1..*" -- "*" Course : teaches
Faculty "1" -- "*" Course : belongs_to

@enduml

